def perform_operation(num1, num2, operator):
    """Perform arithmetic operation based on user input."""
    if operator == '+':
        result = num1 + num2
    elif operator == '-':
        result = num1 - num2
    elif operator == '*':
        result = num1 * num2
    elif operator == '/':
        try:
            result = num1 / num2
        except ZeroDivisionError:
            print("Error: Division by zero is not allowed.")
            result = None
    elif operator == '%':
        result = num1 % num2
    else:
        print("Error: Invalid operator. Please use +, -, *, /, or %.")
        result = None
    return result

def main():
    while True:
        try:
            num1 = float(input("Enter the first number: "))
            num2 = float(input("Enter the second number: "))
            operator = input("Enter the operator (+, -, *, /, or %): ")

            result = perform_operation(num1, num2, operator)

            if result is not None:
                print(f"{num1} {operator} {num2} = {result}")
            else:
                print("Invalid input. Please try again.")

        except ValueError:
            print("Error: Invalid input. Please enter numbers and operators.")

        except Exception as e:
            print(f"Error: {e}. Please try again.")

        again = input("Do you want to perform another operation? (yes/no): ").lower()
        if again != 'yes':
            break

if __name__ == "__main__":
    main()
```

This program will keep asking for user input until the user decides to quit. It will handle invalid inputs, division by zero errors, and provide clear error messages when needed.
